def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 1 and history[-1][1] == 'D':
        return 'C'

    opp = [h[1] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    last_me, last_opp = history[-1]

    if opp_def * 2 > n:
        return 'D'

    if last_opp == 'D':
        cons_d = 0
        for a in reversed(opp):
            if a == 'D':
                cons_d += 1
            else:
                break
        if opp_def * 20 > n * 7:
            return 'D'
        if cons_d >= 3:
            if rng.random() < 0.1:
                return 'C'
        elif cons_d == 2:
            if rng.random() < 0.2:
                return 'C'
        return 'D'
    else:
        return 'C'
